<script setup lang="ts">
import { computed } from 'vue'
import type { RegistryDialog } from '~/types/registry'
import { registryActions } from '~/utils/registry'
const props=defineProps<{dialog:RegistryDialog|null;busy?:boolean}>(),emit=defineEmits<{close:[];confirm:[];reconcile:[];prepareAgain:[]}>()
const shown=computed({get:()=>!!props.dialog,set:value=>{if(!value&&!props.busy)emit('close')}})
</script>
<template><UiModal v-model="shown" class="registry-action-modal" :title="dialog?registryActions[dialog.action].title:'Действие со сценарием'"><div v-if="dialog" class="registry-confirm"><p class="registry-dialog-name">«{{ dialog.title }}»</p><p>{{ registryActions[dialog.action].description }}</p><UiState v-if="dialog.phase==='checking'" kind="loading" title="Перечитываем сценарий" /><UiAlert v-if="dialog.message" :tone="dialog.phase==='done'?'info':dialog.phase==='blocked'||dialog.phase==='error'?'error':'warning'">{{ dialog.message }}</UiAlert><UiAlert v-if="dialog.error" tone="error">{{ dialog.error.message }}</UiAlert><p v-if="dialog.action==='delete'" class="muted">Архивирование сохраняет сценарий в разделе «Архив» и позволяет вернуть его в активный список. Удаление не имеет такой операции восстановления.</p><div class="registry-dialog-actions"><UiButton variant="secondary" :disabled="busy" @click="emit('close')">{{ dialog.phase==='done'?'Закрыть':'Отмена' }}</UiButton><UiButton v-if="dialog.phase==='confirm'||dialog.phase==='sending'" :variant="dialog.action==='delete'?'danger':'primary'" :loading="busy" :disabled="busy" @click="emit('confirm')">{{ registryActions[dialog.action].confirm }}</UiButton><UiButton v-if="['uncertain','reconciled'].includes(dialog.phase)" variant="secondary" :disabled="busy" @click="emit('reconcile')">Сверить с сервером</UiButton><UiButton v-if="dialog.canPrepareAgain||dialog.phase==='error'" variant="secondary" :disabled="busy" @click="emit('prepareAgain')">{{ dialog.canPrepareAgain?'Начать новое подтверждение':'Перечитать данные' }}</UiButton></div></div></UiModal></template>
